import re
import errno
import time


def get_uptime_facts(module):
    sysctl_cmd = module.get_bin_path('sysctl')
    if not sysctl_cmd:
        raise ValueError('Unable to find sysctl')

    try:
        rc, out, err = module.run_command([sysctl_cmd, '-n', 'kern.boottime'])
    except OSError as exc:
        if exc.errno == errno.ENOENT:
            raise ValueError('Unable to find sysctl: %s' % exc)
        module.warn('Unable to read sysctl: %s' % exc)
        return {}

    boot_time = out.strip()
    if rc != 0 or not boot_time or not re.match(r'^\d+$', boot_time):
        return {}
    return {'uptime_seconds': int(time.time() - int(boot_time))}


def get_sysctl(module, prefixes):
    sysctl_cmd = module.get_bin_path('sysctl')
    if not sysctl_cmd:
        raise ValueError('Unable to find sysctl')
    cmd = [sysctl_cmd]
    cmd.extend(prefixes)

    try:
        rc, out, err = module.run_command(cmd)
    except (IOError, OSError) as exc:
        module.warn('Unable to read sysctl: %s' % exc)
        return dict()
    if rc != 0:
        module.warn('Unable to read sysctl: %s' % err)
        return dict()

    sysctl = dict()
    for line in out.splitlines():
        if not line:
            continue
        if line[0].isspace() and sysctl:
            sysctl[key] += '\n' + line
            continue
        try:
            (key, value) = re.split(r'\s*=\s*|:\s+|\s+', line, maxsplit=1)
        except ValueError as exc:
            module.warn('Unable to split sysctl line (%s): %s' % (line, exc))
            continue
        if not key:
            module.warn('Unable to split sysctl line (%s): empty key' % line)
            continue
        sysctl[key] = value.strip()

    return sysctl
